// Legge il testo estratto dal PDF e lo trasforma nel JSON che il webhook si aspetta
const testo = String($input.first().json.text || '');
const righeTesto = testo.split(/\r?\n/).map(s => s.trim()).filter(Boolean);
const ETICHETTE = ['N° richiesta:', 'Fornitore:', 'Data:', 'Pagamento:', 'Codice'];

function valore(etichetta) {
  const i = righeTesto.findIndex(r => r.startsWith(etichetta));
  if (i < 0) return '';
  const resto = righeTesto[i].slice(etichetta.length).trim();
  if (resto) return ETICHETTE.some(e => resto.startsWith(e)) ? '' : resto;
  const dopo = righeTesto[i + 1] || '';
  return ETICHETTE.some(e => dopo.startsWith(e)) ? '' : dopo;
}

// Articoli: dopo l'intestazione "Quantità", ogni codice è seguito dalla sua quantità "N pz"
const tabella = testo.slice(Math.max(0, testo.indexOf('Quantità')));
const righe = [...tabella.matchAll(/\b([A-Z]{2,}-[A-Z0-9]+)\b[\s\S]*?(\d+)\s*pz\b/g)]
  .map(m => ({ codice: m[1], quantita: Number(m[2]) }));

const body = { richiesta_id: valore('N° richiesta:'), righe };
const forn = valore('Fornitore:');
if (forn) body.fornitore = forn;   // se manca nel PDF non lo invio: lo segnalerà la validazione

return [{ json: { body } }];

// Trasforma la risposta del workflow d'esame in una pagina leggibile per chi ha caricato il PDF
const r = $input.first().json, b = r.body || {}, ris = b.risultato || {};
const a = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/\n/g, '<br>');
let html;
if (r.statusCode === 400) {
  html = `<h2>❌ Ordine non valido</h2><p>${a(b.messaggio)}</p><ul>${(b.errori || []).map(e => `<li>${a(e)}</li>`).join('')}</ul>`;
} else if (b.esito !== 'ok') {
  html = `<h2>❌ Errore</h2><p>${a(b.messaggio || ('Codice ' + r.statusCode))}</p>`;
} else {
  const titolo = b.duplicato ? '♻️ Ordine già elaborato: ti mostro l\'esito salvato' : '✅ Ordine registrato';
  html = `<h2>${titolo}</h2>
<p><b>Richiesta:</b> ${a(b.richiesta_id)} – <b>Stato:</b> ${a(b.stato)} – <b>Priorità:</b> ${a(ris.priorita)}</p>
${(ris.avvisi || []).length ? `<p><b>⚠️ Avvisi:</b></p><ul>${ris.avvisi.map(x => `<li>${a(x)}</li>`).join('')}</ul>` : ''}
<p><b>Messaggio per il fornitore:</b><br>${a(ris.messaggio_fornitore)}</p>
<p><b>Nota per il magazzino:</b><br>${a(ris.nota_magazzino)}</p>
<p><b>Prossimo passo:</b> ${a(ris.prossimo_passo)}</p>`;
}
return [{ json: { html } }];

 // Crea 2 PDF dall'esito dell'ordine: "Nota magazzino" e "Riepilogo ufficio acquisti".
// Solo per ordini NUOVI andati a buon fine (i duplicati non rigenerano documenti).
const r = $('Invia al workflow ordini').first().json;
const b = r.body || {}, ris = b.risultato || {};
if (r.statusCode !== 200 || b.esito !== 'ok' || b.duplicato) {
  return [{ json: { pdf_creati: false, motivo: b.duplicato ? 'Richiesta duplicata: documenti già creati la prima volta' : 'Ordine non valido: nessun documento' } }];
}

// ---------- mini generatore PDF (A4, font Helvetica) ----------
function nuovoPdf() {
  const W = 595, H = 842, M = 45, pagine = [];
  let ops = [], y = H - M;
  const MAP = { 8211: 0x96, 8212: 0x97, 8364: 0x80, 8217: 0x92, 8216: 0x91, 8220: 0x93, 8221: 0x94, 8226: 0x95, 8230: 0x85 };
  const enc = s => { let o = ''; for (const ch of String(s ?? '')) { const c = ch.codePointAt(0);
      const v = c < 256 ? c : MAP[c]; if (v === undefined) continue;
      const t = String.fromCharCode(v); o += (t === '(' || t === ')' || t === '\\') ? '\\' + t : t; } return o; };
  const larg = (s, size) => String(s).length * size * 0.5;
  const nuovaPagina = () => { if (ops.length) pagine.push(ops.join('\n')); ops = []; y = H - M; };
  const spazio = h => { if (y - h < M + 20) nuovaPagina(); };
  const testo = (x, yy, s, size = 10, bold = false, col = '0 0 0') =>
    ops.push(`BT ${col} rg /${bold ? 'F2' : 'F1'} ${size} Tf ${x} ${yy} Td (${enc(s)}) Tj ET`);
  const rett = (x, yy, w, h, col) => ops.push(`${col} rg ${x} ${yy} ${w} ${h} re f`);
  const a_capo = (s, size, maxW) => {
    const out = [];
    String(s ?? '').split('\n').forEach(par => {
      let riga = '';
      par.split(' ').forEach(p => { const t = riga ? riga + ' ' + p : p;
        if (larg(t, size) > maxW && riga) { out.push(riga); riga = p; } else riga = t; });
      out.push(riga);
    });
    return out;
  };
  const api = {
    intestazione(titolo, sotto) {
      testo(M, y - 14, 'QWERTYCOM S.R.L.S.', 16, true, '0.12 0.22 0.39'); y -= 30;
      rett(M, y - 26, W - 2 * M, 26, '0.12 0.22 0.39'); testo(M + 10, y - 18, titolo, 13, true, '1 1 1'); y -= 40;
      if (sotto) { testo(M, y, sotto, 9, false, '0.4 0.4 0.4'); y -= 18; }
    },
    campi(lista) { lista.forEach(([k, v]) => { spazio(16); testo(M, y, k + ':', 10, true); testo(M + 120, y, v, 10); y -= 16; }); y -= 6; },
    titolo(s) { spazio(30); y -= 6; testo(M, y, s, 11, true, '0.12 0.22 0.39'); y -= 16; },
    paragrafo(s, size = 10) { a_capo(s, size, W - 2 * M).forEach(l => { spazio(14); testo(M, y, l, size); y -= 14; }); y -= 4; },
    tabella(col, righe, totale) {
      const xs = []; let x = M; col.forEach(c => { xs.push(x); x += c[1]; });
      spazio(40); rett(M, y - 6, W - 2 * M, 20, '0.85 0.89 0.95');
      col.forEach((c, i) => testo(xs[i] + 5, y, c[0], 9, true, '0.12 0.22 0.39')); y -= 20;
      righe.forEach((rr, n) => { spazio(20); if (n % 2) rett(M, y - 6, W - 2 * M, 20, '0.96 0.97 0.98');
        rr.forEach((v, i) => testo(xs[i] + 5, y, a_capo(v, 9, col[i][1] - 8)[0], 9)); y -= 20; });
      if (totale) { spazio(20); testo(xs[xs.length - 2] + 5, y, totale[0], 9, true); testo(xs[xs.length - 1] + 5, y, totale[1], 9, true); y -= 20; }
      y -= 6;
    },
    async file(nome) {
      nuovaPagina();
      const obj = [], n = pagine.length, kids = pagine.map((_, i) => `${5 + 2 * i} 0 R`).join(' ');
      obj.push('<< /Type /Catalog /Pages 2 0 R >>');
      obj.push(`<< /Type /Pages /Kids [${kids}] /Count ${n} >>`);
      obj.push('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');
      obj.push('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');
      pagine.forEach((p, i) => {
        p += `\nBT 0.55 0.55 0.55 rg /F1 8 Tf ${M} 25 Td (${enc('Documento generato automaticamente – pagina ' + (i + 1) + ' di ' + n)}) Tj ET`;
        obj.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${W} ${H}] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ${6 + 2 * i} 0 R >>`);
        obj.push(`<< /Length ${Buffer.byteLength(p, 'latin1')} >>\nstream\n${p}\nendstream`);
      });
      let pdf = '%PDF-1.4\n'; const off = [];
      obj.forEach((o, i) => { off.push(Buffer.byteLength(pdf, 'latin1')); pdf += `${i + 1} 0 obj\n${o}\nendobj\n`; });
      const xref = Buffer.byteLength(pdf, 'latin1');
      pdf += `xref\n0 ${obj.length + 1}\n0000000000 65535 f \n` + off.map(o => String(o).padStart(10, '0') + ' 00000 n \n').join('');
      pdf += `trailer\n<< /Size ${obj.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;
      return await this_helpers.prepareBinaryData(Buffer.from(pdf, 'latin1'), nome, 'application/pdf');
    }
  };
  return api;
}
const this_helpers = this.helpers;
// ----------------------------------------------------------------

const oggi = new Date().toLocaleDateString('it-IT');
const id = b.richiesta_id, righe = ris.righe || [];
const avvisi = (ris.avvisi || []).length ? ris.avvisi : ['Nessun avviso'];
const eur = n => n == null ? '–' : Number(n).toFixed(2).replace('.', ',') + ' €';

// 1) Nota magazzino
const mag = nuovoPdf();
mag.intestazione('NOTA MAGAZZINO – ' + id, 'Merce in arrivo da controllare al ricevimento');
mag.campi([['Richiesta', id], ['Data', oggi], ['Priorità', ris.priorita || '']]);
mag.tabella([['Codice', 100], ['Descrizione', 245], ['Pezzi attesi', 80], ['Confezioni', 80]],
  righe.map(x => [x.codice, x.descrizione || 'NON A CATALOGO', String(x.quantita_pezzi ?? ''), x.confezioni == null ? '–' : String(x.confezioni)]));
mag.titolo('Indicazioni per il magazzino'); mag.paragrafo(ris.nota_magazzino);
mag.titolo('Avvisi'); avvisi.forEach(a => mag.paragrafo('• ' + a));
mag.titolo('Controllo al ricevimento'); mag.paragrafo('Firma: ______________________     Data: ____________');

// 2) Riepilogo ufficio acquisti
const uff = nuovoPdf();
uff.intestazione('RIEPILOGO UFFICIO ACQUISTI – ' + id, 'Uso interno');
uff.campi([['Richiesta', id], ['Data', oggi], ['Stato', b.stato], ['Priorità', ris.priorita || ''], ['Prossimo passo', ris.prossimo_passo || '']]);
const totale = righe.reduce((s, x) => s + (Number(x.importo) || 0), 0);
uff.tabella([['Codice', 95], ['Descrizione', 200], ['Pezzi', 50], ['Confez.', 55], ['Importo', 105]],
  righe.map(x => [x.codice, x.descrizione || 'NON A CATALOGO', String(x.quantita_pezzi ?? ''), x.confezioni == null ? '–' : String(x.confezioni), eur(x.importo)]),
  ['Totale', eur(totale)]);
uff.titolo('Avvisi'); avvisi.forEach(a => uff.paragrafo('• ' + a));
uff.titolo('Messaggio da inviare al fornitore'); uff.paragrafo(ris.messaggio_fornitore);

return [{ json: { pdf_creati: true, richiesta_id: id },
  binary: { magazzino: await mag.file('Nota magazzino ' + id + '.pdf'), ufficio: await uff.file('Riepilogo ufficio ' + id + '.pdf') } }];
